use vstd::prelude::*;

verus! {
    fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
        requires
            a.len() < 0x1_0000_0000, // Ensure the length of the vector is within a reasonable bound to avoid overflow
        ensures
            result.len() == a.len() && // The output vector has the same length as the input
            forall|i: nat| 0 <= i < a.len() ==> result[i] == a[i] // For all valid indices, the elements are equal
    {
        let mut result: Vec<T> = Vec::new(); // Initialize the result vector
        let mut idx: nat = 0; // Initialize the index

        while idx < a.len() as nat
            invariant
                idx <= a.len() as nat, // Ensure idx does not exceed the length of a
                result.len() == idx, // The length of result is equal to the current index
                forall|i: nat| 0 <= i < idx ==> result[i] == a[i], // Elements copied so far are correct
            decreases a.len() as nat - idx, // Decreases clause for termination
        {
            result.push(a[idx as usize]); // Copy the element from a to result
            idx = idx + 1; // Increment the index
        }

        result // Return the result vector
    }
}

